// Hyniqe Growth website. The health check uses the product's own rules
// (health-core.js and data.js are generated by scripts/build-site.ts).
import { checkPage } from './health-core.js';
import { AGENTS, DEMO_SITES, RULES } from './data.js';

// Where the links point. They go to main, so they work once the growth branch is merged.
const REPO = 'https://github.com/HiteshChakravarti/Hyniqe';
const BRANCH = 'main';
const LINKS = {
  repo: `${REPO}/tree/${BRANCH}/growth`,
  samples: `${REPO}/blob/${BRANCH}/growth/samples/chai-and-crumb-autopilot.md`,
  samplesSaas: `${REPO}/blob/${BRANCH}/growth/samples/ledgerly-copilot.md`,
  hyniqe: REPO,
};
for (const [attr, href] of [['data-repo', LINKS.repo], ['data-samples', LINKS.samples], ['data-samples-saas', LINKS.samplesSaas], ['data-hyniqe', LINKS.hyniqe]]) {
  document.querySelectorAll(`[${attr}]`).forEach((a) => { a.href = href; a.rel = 'noopener'; });
}

const $ = (s) => document.querySelector(s);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const agentName = (id) => AGENTS.find((a) => a.id === id)?.name ?? id;

// ---- team ----
$('#agents').innerHTML = AGENTS.map((a) => `
  <div class="agent reveal${a.id === 'marketing-lead' ? ' lead' : ''}">
    <div class="top"><div class="av">${esc(a.name[0])}</div><div><div class="name">${esc(a.name)}</div><div class="role">${esc(a.title)}</div></div></div>
    <p>${esc(a.does)}</p>
    <div class="covers">Covers the job of: ${esc(a.replaces)}</div>
  </div>`).join('');

// ---- health check ----
const ORDER = { critical: 0, warning: 1, info: 2 };
const COLOR = { 'Leaking leads': '#b3261e', 'Needs work': '#a8650a', Healthy: '#17704f' };

function ring(score, color) {
  const r = 40, c = 2 * Math.PI * r, off = c * (1 - score / 100);
  return `<svg class="ring" viewBox="0 0 96 96" role="img" aria-label="Score ${score} out of 100">
    <circle cx="48" cy="48" r="${r}" fill="none" stroke="#e2dccd" stroke-width="8"/>
    <circle cx="48" cy="48" r="${r}" fill="none" stroke="${color}" stroke-width="8" stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${off}" transform="rotate(-90 48 48)"/>
    <text x="48" y="57" text-anchor="middle" fill="${color}">${score}</text></svg>`;
}

function show(h) {
  const color = COLOR[h.verdict];
  const failed = h.findings.filter((f) => !f.passed).sort((a, b) => ORDER[a.severity] - ORDER[b.severity]);
  const passed = h.findings.filter((f) => f.passed);
  const el = $('#result');
  el.className = 'result';
  el.innerHTML = `
    <div class="verdict-row">${ring(h.score, color)}<div><h3 style="color:${color}">${esc(h.verdict)}</h3><p>${esc(h.summary)}</p></div></div>
    <ul class="findings">
      ${failed.map((f) => `<li><span class="dot ${f.severity}"></span><div><b>${esc(f.title)}</b><div class="ev">${esc(f.evidence)}</div><div class="fix">${esc(f.fix)}</div></div><span class="who">${esc(agentName(f.agent))} fixes</span></li>`).join('')}
    </ul>
    <details class="passed-toggle"><summary>${passed.length} checks passed</summary><ul class="findings">${passed.map((f) => `<li><span class="dot pass"></span><div><b>${esc(f.title)}</b><div class="ev">${esc(f.evidence)}</div></div><span></span></li>`).join('')}</ul></details>`;
}

function run(url, html) {
  $('#err').textContent = '';
  if (!html.trim()) {
    $('#err').textContent = 'Paste your page\'s HTML first, or try one of the sample sites.';
    $('#html').focus();
    return;
  }
  if (!/<[a-z!]/i.test(html)) {
    $('#err').textContent = 'That doesn\'t look like HTML. Open your site, press Ctrl+U, and copy the whole page source.';
    return;
  }
  const found = html.match(/<link[^>]+rel=["']canonical["'][^>]*href=["']([^"']+)/i)?.[1] || html.match(/<meta[^>]+property=["']og:url["'][^>]*content=["']([^"']+)/i)?.[1];
  show(checkPage(RULES, { url: url || found || 'pasted-html', html }));
}

$('#html').addEventListener('input', () => { $('#err').textContent = ''; });
$('#run').addEventListener('click', () => run('', $('#html').value));
document.querySelectorAll('[data-demo]').forEach((b) => b.addEventListener('click', () => {
  const d = DEMO_SITES[b.dataset.demo];
  $('#html').value = d.html;
  run(d.url, d.html);
}));

// ---- small touches ----
const nav = $('#nav');
addEventListener('scroll', () => nav.classList.toggle('scrolled', scrollY > 8), { passive: true });
const io = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } }), { threshold: 0.12 });
document.querySelectorAll('.reveal').forEach((el) => io.observe(el));
